{"command":"cat > src/cli.js <<'EOF'
#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'

class ConfError extends Error {}
const fail = (m) => { throw new ConfError(m) }

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const newTable = () => ({ type: 'table', map: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'

function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  for (let n = 0; n < lines.length; n++) {
    try {
      current = parseLine(lines[n], root, current)
    } catch (e) {
      if (e instanceof ConfError) {
        process.stderr.write(`error: line ${n + 1}: ${e.message}\n`)
        process.exit(2)
      }
      throw e
    }
  }
  return root
}

function parseLine(line, root, current) {
  let i = 0
  const skipWs = () => { while (i < line.length && isWs(line[i])) i++ }
  const atEnd = () => { skipWs(); return i >= line.length || line[i] === '#' || line[i] === ';' }
  skipWs()
  if (i >= line.length || line[i] === '#' || line[i] === ';') return current

  function parseString(q) {
    i++
    let s = ''
    for (;;) {
      if (i >= line.length) fail('unterminated string')
      const c = line[i]
      if (c === q) { i++; return s }
      if (q === '"' && c === '\\') {
        i++
        if (i >= line.length) fail('unterminated string')
        const e = line[i]
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) { s += map[e]; i++ } else if (e === 'u') {
          const h = line.slice(i + 1, i + 5)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          s += String.fromCharCode(parseInt(h, 16)); i += 5
        } else fail(`invalid escape \\${String.fromCodePoint(line.codePointAt(i))}`)
        continue
      }
      s += c; i++
    }
  }

  function parseName() {
    skipWs()
    const c = line[i]
    if (c === '"' || c === "'") return parseString(c)
    const st = i
    while (i < line.length && /[A-Za-z0-9_-]/.test(line[i])) i++
    if (i === st) fail('expected a name')
    return line.slice(st, i)
  }

  function parseDotted() {
    const names = [parseName()]
    for (;;) {
      skipWs()
      if (line[i] === '.') { i++; names.push(parseName()) } else return names
    }
  }

  // Walk the key path (all but the last name), creating tables on the way.
  function walk(base, names, prefix) {
    let t = base
    const path = [...prefix]
    for (const name of names) {
      path.push(name)
      let child = t.map.get(name)
      if (!child) { child = newTable(); t.map.set(name, child) }
      if (child.type === 'array' && child.aot) child = child.items[child.items.length - 1]
      if (child.type !== 'table') fail(`${path.join('.')} is not a table`)
      t = child
    }
    return t
  }

  function parseValue(inContainer) {
    skipWs()
    const c = line[i]
    if (i >= line.length || c === '#' && false) fail('expected a value')
    if (c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { type: 'string', value: parseString(c) }
    if (c === '[') {
      i++
      const items = []
      for (;;) {
        if (atEnd()) fail('unterminated array')
        if (line[i] === ']') { i++; return { type: 'array', items, aot: false } }
        items.push(parseValue(true))
        if (atEnd()) fail('unterminated array')
        if (line[i] === ',') { i++; continue }
        if (line[i] === ']') continue
        fail('unterminated array')
      }
    }
    if (c === '{') {
      i++
      const t = newTable()
      let first = true
      for (;;) {
        if (atEnd()) fail('unterminated inline table')
        if (line[i] === '}' && first) { i++; return t }
        first = false
        const names = parseDotted()
        skipWs()
        if (line[i] !== '=') fail('expected = in an inline table')
        i++
        assign(t, names, parseValue(true), [])
        if (atEnd()) fail('unterminated inline table')
        if (line[i] === ',') { i++; continue }
        if (line[i] === '}') { i++; return t }
        fail('unterminated inline table')
      }
    }
    const st = i
    while (i < line.length && !isWs(line[i]) && !',]}'.includes(line[i])) i++
    const tok = line.slice(st, i)
    if (tok === 'true' || tok === 'false') return { type: 'boolean', value: tok === 'true' }
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(tok)) return { type: 'integer', value: BigInt(tok.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(tok)) {
      return { type: 'float', value: Number(tok.replace(/_/g, '')) }
    }
    fail(`invalid value ${tok}`)
  }

  function assign(base, names, value, prefix) {
    const t = walk(base, names.slice(0, -1), prefix)
    const last = names[names.length - 1]
    if (t.map.has(last)) fail(`key ${pathOf(base, names, root, current)} is defined twice`)
    t.map.set(last, value)
  }

  function pathOf(base, names) {
    const p = base === current ? curPath : []
    return [...p, ...names].join('.')
  }

  if (line[i] === '[') {
    const aot = line[i + 1] === '['
    i += aot ? 2 : 1
    const names = parseDotted()
    skipWs()
    if (line[i] !== ']') fail('unterminated table header')
    i++
    if (aot) {
      if (line[i] !== ']') fail('unterminated table header')
      i++
    }
    if (!atEnd()) fail('trailing text after a table header')
    const parent = walk(root, names.slice(0, -1), [])
    const last = names[names.length - 1]
    const full = names.join('.')
    const existing = parent.map.get(last)
    curPath = names
    if (aot) {
      let arr = existing
      if (!arr) { arr = { type: 'array', items: [], aot: true }; parent.map.set(last, arr) }
      if (arr.type !== 'array' || !arr.aot) fail(`${full} is not an array of tables`)
      const t = newTable()
      t.header = true
      arr.items.push(t)
      return t
    }
    if (!existing) {
      const t = newTable(); t.header = true; parent.map.set(last, t); return t
    }
    if (existing.type !== 'table') fail(`${full} is not a table`)
    if (existing.header) fail(`table ${full} is defined twice`)
    existing.header = true
    return existing
  }

  const names = parseDotted()
  skipWs()
  if (line[i] !== '=') fail('expected key = value')
  i++
  const value = parseValue(false)
  if (!atEnd()) fail('trailing text after a value')
  assign(current, names, value, [])
  return current
}
let curPath = []

const typeName = (n) => n.type

function sortedEntries(map) {
  const cp = (s) => Array.from(s, (c) => c.codePointAt(0))
  return [...map.entries()].sort(([a], [b]) => {
    const x = cp(a), y = cp(b)
    for (let k = 0; k < Math.min(x.length, y.length); k++) if (x[k] !== y[k]) return x[k] - y[k]
    return x.length - y.length
  })
}

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  switch (n.type) {
    case 'table': {
      const es = sortedEntries(n.map)
      if (!es.length) return '{}'
      return '{\n' + es.map(([k, v]) => `${pad}${JSON.stringify(k)}: ${toJson(v, ind + 1)}`).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!n.items.length) return '[]'
      return '[\n' + n.items.map((v) => pad + toJson(v, ind + 1)).join(',\n') + '\n' + end + ']'
    case 'integer': return n.value.toString()
    default: return JSON.stringify(n.value)
  }
}

function toKeys(n, path, out) {
  if (n.type === 'table') {
    for (const [k, v] of sortedEntries(n.map)) {
      const p = path === null ? k : `${path}.${k}`
      out.push(`${p} ${typeName(v)}`)
      toKeys(v, p, out)
    }
  } else if (n.type === 'array') {
    n.items.forEach((v, idx) => {
      const p = `${path}[${idx}]`
      out.push(`${p} ${typeName(v)}`)
      toKeys(v, p, out)
    })
  }
}

const doc = parseDocument(readFileSync(0, 'utf8'))
if (mode === 'json') process.stdout.write(toJson(doc, 0) + '\n')
else {
  const out = []
  toKeys(doc, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
