const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const num = (v) => ({ k: 'n', v })
const err = (v) => ({ k: 'e', v })

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'values' && mode[0] !== 'deps')) fail('error: usage: cli.js values|deps')

// ---- addresses
function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = m[1].toUpperCase()
  return { col, row, key: col + row }
}
const colIdx = (c) => (c.length === 1 ? c.charCodeAt(0) - 64 : (c.charCodeAt(0) - 64) * 26 + c.charCodeAt(1) - 64)
const cmpAddr = (a, b) => colIdx(a.col) - colIdx(b.col) || a.row - b.row
function colFromIdx(i) {
  return i <= 26 ? String.fromCharCode(64 + i) : String.fromCharCode(64 + Math.floor((i - 1) / 26)) + String.fromCharCode(65 + ((i - 1) % 26))
}
function expand(a, b) {
  const c1 = Math.min(colIdx(a.col), colIdx(b.col)), c2 = Math.max(colIdx(a.col), colIdx(b.col))
  const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
  const out = []
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push({ col: colFromIdx(c), row: r, key: colFromIdx(c) + r })
  return out
}

// ---- parse the sheet
const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
lines.forEach((line, i) => {
  const s = line.replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') return
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(s)
  const a = parseAddr(m[1])
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${m[1]}`)
  if (cells.has(a.key)) fail(`error: line ${i + 1}: cell ${a.key} is declared twice`)
  cells.set(a.key, { addr: a, content: m[2] })
})
const ordered = [...cells.values()].sort((x, y) => cmpAddr(x.addr, y.addr))

// ---- formula parsing
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) { toks.push({ t: 'num', v: parseFloat(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) { toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[-+*/^=<>(),:])/.exec(src.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  let bad = false
  const isOp = (v, o = 0) => toks[p + o] && toks[p + o].t === 'op' && toks[p + o].v === v
  const isWord = (o = 0) => toks[p + o] && toks[p + o].t === 'word' && !['TRUE', 'FALSE'].includes(toks[p + o].v.toUpperCase()) && !isOp('(', o + 1)
  const fl = () => { throw new Error('syntax') }
  function range() {
    const a = toks[p].v, b = toks[p + 2].v
    p += 3
    return { t: 'range', a: parseAddr(a), b: parseAddr(b) }
  }
  function cmp() {
    let l = add()
    while (toks[p] && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { t: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const tk = toks[p]
    if (!tk) fl()
    if (tk.t === 'num') { p++; return { t: 'num', v: tk.v } }
    if (isOp('(')) {
      p++
      const e = cmp()
      if (!isOp(')')) fl()
      p++
      return e
    }
    if (tk.t === 'word') {
      const up = tk.v.toUpperCase()
      if (isOp('(', 1)) {
        p += 2
        const args = []
        if (isOp(')')) p++
        else {
          for (;;) {
            if (isWord() && isOp(':', 1) && isWord(2)) {
              args.push(range())
            } else args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fl()
          }
        }
        return { t: 'call', name: up, args }
      }
      if (up === 'TRUE' || up === 'FALSE') { p++; return { t: 'bool', v: up === 'TRUE' } }
      if (isOp(':', 1) && isWord(2)) { bad = true; return range() }
      p++
      return { t: 'ref', a: parseAddr(tk.v) }
    }
    fl()
  }
  try {
    const e = cmp()
    if (p < toks.length) fl()
    return { e, bad }
  } catch (x) {
    if (x.message === 'syntax') return null
    throw x
  }
}

function collectDeps(n, set) {
  if (!n) return
  switch (n.t) {
    case 'ref': if (n.a) set.set(n.a.key, n.a); break
    case 'range': if (n.a && n.b) for (const a of expand(n.a, n.b)) set.set(a.key, a); break
    case 'bin': collectDeps(n.l, set); collectDeps(n.r, set); break
    case 'un': collectDeps(n.e, set); break
    case 'call': n.args.forEach((a) => collectDeps(a, set)); break
  }
}

// ---- literals & evaluation
function literal(c) {
  if (c === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(parseFloat(c))
  if (ERRS.includes(c)) return err(c)
  return { k: 's', v: c }
}

for (const cell of ordered) {
  if (cell.content[0] === '=') {
    const r = parseFormula(cell.content.slice(1))
    cell.ast = r && !r.bad ? r.e : null
    cell.parsed = r
  } else cell.lit = literal(cell.content)
}

const memo = new Map()
const active = new Set()
function cellValue(a) {
  if (!a) return err('#REF!')
  const cell = cells.get(a.key)
  if (!cell) return num(0)
  if (cell.lit) return cell.lit
  if (memo.has(a.key)) return memo.get(a.key)
  if (active.has(a.key)) return err('#CYCLE!')
  active.add(a.key)
  const v = cell.ast ? ev(cell.ast) : err('#ERR!')
  active.delete(a.key)
  memo.set(a.key, v)
  return v
}

const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
function toNum(v) {
  if (v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const rank = { n: 0, s: 1, b: 2 }
function compare(x, y) {
  if (x.k !== y.k) return rank[x.k] - rank[y.k]
  if (x.k === 'b') return Number(x.v) - Number(y.v)
  return x.v < y.v ? -1 : x.v > y.v ? 1 : 0
}

function rangeVals(n) {
  if (!n.a || !n.b) return [err('#REF!')]
  return expand(n.a, n.b).map(cellValue)
}
function argVals(n) {
  return n.t === 'range' ? rangeVals(n) : [ev(n)]
}

function ev(n) {
  switch (n.t) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'b', v: n.v }
    case 'ref': return cellValue(n.a)
    case 'range': return err('#ERR!')
    case 'un': {
      const v = ev(n.e)
      if (v.k === 'e') return v
      const x = toNum(v)
      if (x.k === 'e') return x
      return n.op === '-' ? num(-x.v) : x
    }
    case 'bin': {
      const l = ev(n.l)
      if (l.k === 'e') return l
      const r = ev(n.r)
      if (r.k === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const c = compare(l, r)
        const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
        return { k: 'b', v: res }
      }
      const a = toNum(l)
      if (a.k === 'e') return a
      const b = toNum(r)
      if (b.k === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        case '^': return fin(Math.pow(a.v, b.v))
      }
      return err('#ERR!')
    }
    case 'call': return call(n)
  }
  return err('#ERR!')
}

function call(n) {
  const { name, args } = n
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return err('#NAME?')
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const cv = argVals(args[0])
    const e = cv.find((v) => v.k === 'e')
    if (e) return e
    if (cv.length !== 1) return err('#VALUE!')
    const c = cv[0]
    let t
    if (c.k === 'b') t = c.v
    else if (c.k === 'n') t = c.v !== 0
    else return err('#VALUE!')
    const vs = argVals(args[t ? 1 : 2])
    return vs.find((v) => v.k === 'e') || (vs.length === 1 ? vs[0] : err('#VALUE!'))
  }
  if (name === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    const vs = argVals(args[0])
    const e = vs.find((v) => v.k === 'e')
