{"file_path":"src/sheet.js","content":"export class SheetError extends Error {}

export function colNum(letters) {
  return letters.length === 1
    ? letters.charCodeAt(0) - 64
    : (letters.charCodeAt(0) - 64) * 26 + letters.charCodeAt(1) - 64
}

export function colName(n) {
  return n <= 26 ? String.fromCharCode(64 + n) : String.fromCharCode(64 + Math.floor((n - 1) / 26)) + String.fromCharCode(65 + ((n - 1) % 26))
}

// Returns {col,row} or null when not an addressable address (input upper-cased).
export function parseAddr(s) {
  const m = /^([A-Z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: colNum(m[1]), row }
}

export const key = (col, row) => colName(col) + row

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cells = new Map()
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
    const addr = m[1].toUpperCase()
    const a = parseAddr(addr)
    if (!a) throw new SheetError(`error: line ${i + 1}: invalid cell address ${addr}`)
    const k = key(a.col, a.row)
    if (cells.has(k)) throw new SheetError(`error: line ${i + 1}: cell ${k} is declared twice`)
    cells.set(k, { col: a.col, row: a.row, content: m[2] })
  })
  return cells
}
"}

