const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

export function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  // Advance one code point, tracking position.
  const adv = () => {
    const c = s[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else col++
    return c
  }
  const fail = (l, c, reason) => {
    throw new ScanError(l, c, reason)
  }

  // Consume a run of digits (per predicate) with single underscores between digits.
  const digitRun = (pred) => {
    let any = false
    while (i < n) {
      if (pred(s[i])) {
        adv()
        any = true
      } else if (s[i] === '_' && any && pred(s[i - 1]) && pred(s[i + 1])) adv()
      else break
    }
    return any
  }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      adv()
      continue
    }
    const sl = line
    const sc = col
    const start = i

    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      adv()
      adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (s[i] === '/' && s[i + 1] === '*') {
          adv()
          adv()
          depth++
        } else if (s[i] === '*' && s[i + 1] === '/') {
          adv()
          adv()
          depth--
        } else adv()
      }
      if (depth > 0) fail(sl, sc, 'unterminated block comment')
      continue
    }

    if (c === 'r' && s[i + 1] === '"') {
      adv()
      adv()
      const bodyStart = i
      while (i < n && s[i] !== '"') adv()
      if (i >= n) fail(sl, sc, 'unterminated string')
      const value = s.slice(bodyStart, i).join('')
      adv()
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(value) })
      continue
    }

    if (isIdStart(c)) {
      while (i < n && isIdChar(s[i])) adv()
      const word = s.slice(start, i).join('')
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(word) ? 'keyword' : 'ident', body: word })
      continue
