      if (radixPred) {
        adv()
        adv()
        if (!digitRun(radixPred)) bad = true
      } else {
        digitRun(isDigit)
        if (s[i] === '.' && isDigit(s[i + 1])) {
          adv()
          digitRun(isDigit)
        }
        if (s[i] === 'e' || s[i] === 'E') {
          if (isDigit(s[i + 1])) {
            adv()
            digitRun(isDigit)
          } else if ((s[i + 1] === '+' || s[i + 1] === '-') && isDigit(s[i + 2])) {
            adv()
            adv()
            digitRun(isDigit)
          }
        }
      }
      if (bad || isIdChar(s[i])) {
        while (i < n && isIdChar(s[i])) adv()
        fail(sl, sc, `invalid number ${s.slice(start, i).join('')}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'number', body: s.slice(start, i).join('') })
      continue
    }

