      adv()
      let value = ''
      for (;;) {
        if (i >= n) fail(sl, sc, 'unterminated string')
        const ch = s[i]
        if (ch === '"') {
          adv()
          break
        }
        if (ch === '\n') fail(line, col, 'newline in string')
        if (ch !== '\\') {
          value += adv()
          continue
        }
        const el = line
        const ec = col
        adv()
        if (i >= n) fail(sl, sc, 'unterminated string')
        const e = adv()
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) value += simple[e]
        else if (e === 'x') {
          if (isHex(s[i]) && isHex(s[i + 1])) {
            value += String.fromCharCode(parseInt(s[i] + s[i + 1], 16))
            adv()
            adv()
          } else fail(el, ec, 'invalid escape \\x')
        } else if (e === 'u') {
          if (s[i] !== '{') fail(el, ec, 'invalid escape \\u')
          let j = i + 1
          let hex = ''
          while (isHex(s[j])) hex += s[j++]
          if (hex === '' || s[j] !== '}' || parseInt(hex, 16) > 0x10ffff) fail(el, ec, 'invalid escape \\u')
          value += String.fromCodePoint(parseInt(hex, 16))
          while (i <= j) adv()
        } else fail(el, ec, `invalid escape \\${e}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(value) })
      continue
    }

