  process.exit(2)
}

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function int(v, least) {
  return INT.test(v) && BigInt(v) >= BigInt(least) ? BigInt(v) : null
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i].trim()
    if (raw === '' || raw[0] === '#') continue
    const t = raw.split(/\s+/)
    const fail = (r) => new Fail(`line ${i + 1}: ${r}`)
    const late = () => { if (events.length) throw fail('declarations must come before the first event') }
    const num = (field, v, least) => {
      const n = int(v, least)
      if (n === null) throw fail(`${field} must be an integer of at least ${least}`)
      return n
    }
    switch (t[0]) {
      case 'bucket': {
        if (t.length !== 5) throw fail('expected bucket <name> <capacity> <refill> <per>')
        late()
        if (!NAME.test(t[1])) throw fail(`invalid policy name ${t[1]}`)
        if (policies.has(t[1])) throw fail(`policy ${t[1]} is declared twice`)
        const capacity = num('capacity', t[2], 1)
        const refill = num('refill', t[3], 0)
        const per = num('per', t[4], 1)
        policies.set(t[1], { name: t[1], kind: 'bucket', capacity, refill, per, st: new Map() })
        break
      }
      case 'window': {
        if (t.length !== 4) throw fail('expected window <name> <limit> <span>')
        late()
        if (!NAME.test(t[1])) throw fail(`invalid policy name ${t[1]}`)
        if (policies.has(t[1])) throw fail(`policy ${t[1]} is declared twice`)
        const limit = num('limit', t[2], 0)
        const span = num('span', t[3], 1)
        policies.set(t[1], { name: t[1], kind: 'window', limit, span, st: new Map() })
        break
      }
      case 'route': {
        if (t.length < 3) throw fail('expected route <prefix> <policy>...')
        late()
        if (!NAME.test(t[1])) throw fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) throw fail(`prefix ${t[1]} is routed twice`)
        const list = []
        for (const n of t.slice(2)) {
          if (!policies.has(n)) throw fail(`unknown policy ${n}`)
          list.push(policies.get(n))
        }
        routes.set(t[1], list)
        break
      }
      case 'event': {
        if (t.length !== 3) throw fail('expected event <tick> <key>')
        const tick = num('tick', t[1], 0)
        if (!NAME.test(t[2])) throw fail(`invalid key ${t[2]}`)
        if (lastTick !== null && tick < lastTick) throw fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: t[2] })
        break
      }
      default:
        throw fail(`unknown directive ${t[0]}`)
    }
  }
  return { routes, events }
