        const per = num('per', t[4], 1)
        policies.set(t[1], { name: t[1], kind: 'bucket', capacity, refill, per, st: new Map() })
        break
      }
      case 'window': {
        if (t.length !== 4) throw fail('expected window <name> <limit> <span>')
        late()
        if (!NAME.test(t[1])) throw fail(`invalid policy name ${t[1]}`)
        if (policies.has(t[1])) throw fail(`policy ${t[1]} is declared twice`)
        const limit = num('limit', t[2], 0)
        const span = num('span', t[3], 1)
