import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  const E = (m) => fail(`error: line ${n}: ${m}`)
  if (w[0] === 'candidates') {
    if (cands !== null || ballots.length) E('candidates must be declared once, before any ballot')
    if (w.length < 2) E('expected candidates <name>...')
    const seen = new Set()
    for (const name of w.slice(1)) {
      if (!NAME.test(name)) E(`invalid candidate name ${name}`)
      if (seen.has(name)) E(`candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = w.slice(1)
  } else if (w[0] === 'ballot') {
    if (cands === null) E('candidates must be declared once, before any ballot')
    if (w.length < 3) E('expected ballot <count> <candidate>...')
    if (!/^[1-9][0-9]*$/.test(w[1])) E('count must be a positive integer')
    const seen = new Set()
    for (const name of w.slice(2)) {
      if (!cands.includes(name)) E(`unknown candidate ${name}`)
      if (seen.has(name)) E(`candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    E(`unknown directive ${w[0]}`)
  }
}
if (cands === null) fail('error: no candidates')

let total = 0n
for (const b of ballots) total += b.count
const continuing = new Set(cands)
const history = new Map(cands.map((c) => [c, []]))
const out = []
let roundNo = 0
let result
for (;;) {
  roundNo++
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  for (const [c, v] of counts) history.get(c).push(v)
  const order = [...counts.keys()].sort((a, b) => {
    const d = counts.get(b) - counts.get(a)
    if (d !== 0n) return d > 0n ? 1 : -1
    return a < b ? -1 : a > b ? 1 : 0
  })
  out.push(`round ${roundNo}: ${order.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${total - active}`)
  if (active === 0n) { result = 'no winner'; break }
  const win = order.find((c) => counts.get(c) * 2n > active)
  if (win !== undefined) { result = `winner ${win}`; break }
  let min = counts.get(order[order.length - 1])
  let tied = order.filter((c) => counts.get(c) === min)
  for (let r = 0; r < roundNo && tied.length > 1; r++) {
    let m = history.get(tied[0])[r]
    for (const c of tied) if (history.get(c)[r] < m) m = history.get(c)[r]
    tied = tied.filter((c) => history.get(c)[r] === m)
  }
  const elim = tied.reduce((a, b) => (a > b ? a : b))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
out.push(result)
process.stdout.write((mode === 'tally' ? [`rounds ${roundNo}`, result] : out).join('\n') + '\n')
EOF
