import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const NAME = /^[A-Za-z0-9_-]+$/
let candidates = null
let declared = false
const ballots = []

lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (declared || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    declared = true
    candidates = t.slice(1)
  } else if (t[0] === 'ballot') {
    if (!declared) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!candidates.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: Number(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
})
if (!declared) fail('error: no candidates')

const continuing = new Set(candidates)
const history = new Map(candidates.map((c) => [c, []]))
const out = []
let roundNo = 0
let winner = null
for (;;) {
  roundNo++
  const counts = new Map([...continuing].map((c) => [c, 0]))
  let active = 0
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  let exhausted = 0
  for (const b of ballots) exhausted += b.count
  exhausted -= active
  for (const [c, v] of counts) history.get(c).push(v)
  const listed = [...counts.keys()].sort((a, b) => counts.get(b) - counts.get(a) || (a < b ? -1 : a > b ? 1 : 0))
  let text = `round ${roundNo}: ${listed.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${exhausted}`
  out.push(text)
  if (active === 0) break
  const w = listed.find((c) => counts.get(c) * 2 > active)
  if (w !== undefined) { winner = w; break }
  const min = Math.min(...counts.values())
  let tied = [...counts.keys()].filter((c) => counts.get(c) === min)
  while (tied.length > 1) {
    let k = 0
    for (; k < roundNo; k++) {
      const vals = tied.map((c) => history.get(c)[k])
      const m = Math.min(...vals)
      if (vals.some((v) => v !== m)) {
        tied = tied.filter((c) => history.get(c)[k] === m)
        break
      }
    }
    if (k === roundNo) break
  }
  const elim = tied.reduce((a, b) => (a > b ? a : b))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
process.stdout.write((mode === 'rounds' ? out.join('\n') + '\n' : `rounds ${roundNo}\n`) + end + '\n')
EOF
