import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

class ScanError extends Error {
  constructor(pos, reason) {
    super(reason)
    this.pos = pos
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0, line = 1, col = 1
  // position tracking: advance i to j, updating line/col
  const advance = (j) => {
    for (; i < j; i++) {
      const c = s[i]
      if (c === '\n') { line++; col = 1 }
      else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
      else col++
    }
  }
  const emit = (pos, kind, body) => tokens.push({ pos, kind, body })

  while (i < n) {
    const c = s[i]
    const pos = { line, col }
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { advance(i + 1); continue }
    if (c === '/' && s[i + 1] === '/') {
      let j = i
      while (j < n && s[j] !== '\n') j++
      advance(j)
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      let j = i + 2, depth = 1
      while (j < n && depth > 0) {
        if (s[j] === '/' && s[j + 1] === '*') { depth++; j += 2 }
        else if (s[j] === '*' && s[j + 1] === '/') { depth--; j += 2 }
        else j++
      }
      if (depth > 0) throw new ScanError(pos, 'unterminated block comment')
      advance(j)
      continue
    }
    if (c === 'r' && s[i + 1] === '"') {
      let j = i + 2
      while (j < n && s[j] !== '"') j++
      if (j >= n) throw new ScanError(pos, 'unterminated string')
      emit(pos, 'rawstring', JSON.stringify(s.slice(i + 2, j).join('')))
      advance(j + 1)
      continue
    }
    if (isIdStart(c)) {
      let j = i
      while (j < n && isIdChar(s[j])) j++
      const word = s.slice(i, j).join('')
      emit(pos, KEYWORDS.has(word) ? 'keyword' : 'ident', word)
      advance(j)
      continue
    }
    if (isDigit(c)) {
      let j = i
      let bad = false
      const run = (ok) => {
        // digits with single underscores between two digits
        let k = j, any = false
        while (k < n) {
          if (ok(s[k])) { any = true; k++ }
          else if (s[k] === '_' && any && ok(s[k - 1]) && ok(s[k + 1])) k++
          else break
        }
        return k
      }
      const p = s[i + 1]
      const radix = c === '0' && p !== undefined ? { x: isHex, X: isHex, b: (d) => d === '0' || d === '1', B: (d) => d === '0' || d === '1', o: (d) => d >= '0' && d <= '7', O: (d) => d >= '0' && d <= '7' }[p] : undefined
      if (radix) {
        j = i + 2
        const k = run(radix)
        if (k === j) bad = true
        j = k
      } else {
        j = run(isDigit)
        if (s[j] === '.' && isDigit(s[j + 1])) { j++; j = run(isDigit) }
        if (s[j] === 'e' || s[j] === 'E') {
          let k = j + 1
          if (s[k] === '+' || s[k] === '-') k++
          if (isDigit(s[k])) { j = k; j = run(isDigit) }
        }
      }
      if (isIdChar(s[j])) bad = true
      if (bad) {
        while (j < n && isIdChar(s[j])) j++
        throw new ScanError(pos, `invalid number ${s.slice(i, j).join('')}`)
      }
      emit(pos, 'number', s.slice(i, j).join(''))
      advance(j)
      continue
    }
    if (c === '"') {
      let j = i + 1
      let out = ''
      // compute position of s[k] relative to start for errors
      const posAt = (k) => {
        let l = line, cc = col
        for (let m = i; m < k; m++) {
          if (s[m] === '\n') { l++; cc = 1 }
          else if (s[m] === '\t') cc = Math.floor((cc - 1) / 4) * 4 + 5
          else cc++
        }
        return { line: l, col: cc }
      }
      const unterminated = () => new ScanError(pos, 'unterminated string')
      for (;;) {
        if (j >= n) throw unterminated()
        const d = s[j]
        if (d === '"') { j++; break }
        if (d === '\n') throw new ScanError(posAt(j), 'newline in string')
        if (d !== '\\') { out += d; j++; continue }
        const bs = j
        const e = s[j + 1]
        if (e === undefined) throw unterminated()
        const bad = () => new ScanError(posAt(bs), `invalid escape \\${e}`)
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) { out += simple[e]; j += 2; continue }
        if (e === 'x') {
          const a = s[j + 2], b = s[j + 3]
          if (a === undefined || (isHex(a) && b === undefined)) throw unterminated()
          if (!isHex(a) || !isHex(b)) throw bad()
          out += String.fromCharCode(parseInt(a + b, 16))
          j += 4
          continue
        }
        if (e === 'u') {
          if (j + 2 >= n) throw unterminated()
          if (s[j + 2] !== '{') throw bad()
          let k = j + 3, h = ''
          while (k < n && isHex(s[k])) h += s[k++]
          if (k >= n) throw unterminated()
          if (s[k] !== '}' || h === '') throw bad()
          const v = parseInt(h, 16)
          if (v > 0x10ffff) throw bad()
          out += String.fromCodePoint(v)
          j = k + 1
          continue
        }
        throw bad()
      }
      emit(pos, 'string', JSON.stringify(out))
      advance(j)
      continue
    }
    const two = c + (s[i + 1] ?? '')
    if (PUNCT.includes(two)) { emit(pos, 'punct', two); advance(i + 2); continue }
    if (PUNCT.includes(c)) { emit(pos, 'punct', c); advance(i + 1); continue }
    throw new ScanError(pos, `unexpected character ${c}`)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
const input = readFileSync(0, 'utf8')
let tokens
try {
  tokens = scan(input)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.pos.line}:${e.pos.col}: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (args[0] === 'tokens') {
  for (const t of tokens) out += `${t.pos.line}:${t.pos.col} ${t.kind} ${t.body}\n`
} else {
  for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
EOF
