{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(msg, code = 2) {
    super(msg)
    this.code = code
  }
}

const NAME = /^[A-Za-z0-9_.-]+$/
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const tasks = new Map()
  const depLines = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!NAME.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (tasks.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      tasks.set(w[1], { name: w[1], cost: BigInt(w[2]), deps: new Set() })
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      depLines.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const names of depLines) {
    for (const nm of names) if (!tasks.has(nm)) throw new Fail(`error: unknown task ${nm}`)
  }
  for (const [first, ...rest] of depLines) for (const d of rest) tasks.get(first).deps.add(d)
  return tasks
}

function analyze(tasks) {
  const names = [...tasks.keys()].sort(cmp)
  const sortedDeps = new Map(names.map((n) => [n, [...tasks.get(n).deps].sort(cmp)]))
  // cycle detection
  const state = new Map()
  const stack = []
  const visit = (n) => {
    state.set(n, 1)
    stack.push(n)
    for (const d of sortedDeps.get(n)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d))
        cyc.push(d)
        throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(n, 2)
  }
  for (const n of names) if (!state.get(n)) visit(n)

  const info = new Map()
  const calc = (n) => {
    let r = info.get(n)
    if (r) return r
    let start = 0n
    let depth = 0
    for (const d of sortedDeps.get(n)) {
      const x = calc(d)
      if (x.finish > start) start = x.finish
      if (x.depth + 1 > depth) depth = x.depth + 1
    }
    r = { start, finish: start + tasks.get(n).cost, depth }
    info.set(n, r)
    return r
  }
  names.forEach(calc)
  let total = 0n
  for (const r of info.values()) if (r.finish > total) total = r.finish
  return { names, sortedDeps, info, total }
}

function pack(tasks, a, workers) {
  const { names, sortedDeps } = a
  const dependents = new Map(names.map((n) => [n, []]))
  for (const n of names) for (const d of sortedDeps.get(n)) dependents.get(d).push(n)
  const prio = new Map()
  const pr = (n) => {
    if (prio.has(n)) return prio.get(n)
    let best = 0n
    for (const m of dependents.get(n)) {
      const p = pr(m)
      if (p > best) best = p
    }
    const v = best + tasks.get(n).cost
    prio.set(n, v)
    return v
  }
  names.forEach(pr)
  const order = [...names].sort((x, y) => (prio.get(x) > prio.get(y) ? -1 : prio.get(x) < prio.get(y) ? 1 : cmp(x, y)))
  const finish = new Map()
  const freeAt = Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  let t = 0n
  let makespan = 0n
  while (finish.size < names.length) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      const task = order.find((n) => !finish.has(n) && sortedDeps.get(n).every((d) => finish.has(d) && finish.get(d) <= t))
      if (task === undefined) break
      const f = t + tasks.get(task).cost
      finish.set(task, f)
      freeAt[w] = f
      ran[w].push(`${task}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (finish.size >= names.length) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    for (const f of finish.values()) if (f > t && (next === null || f < next)) next = f
    t = next
  }
  return ran.map((r, i) => `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`).join('') + `makespan ${makespan}\n`
}

